sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    // Clear existing values first
    g_form.clearValue('first_name');
    g_form.clearValue('last_name');
    g_form.clearValue('manager');

    if (!newValue) {
        return;
    }

    // Use script include to fetch user details
    var userLookup = new x_1900237_github_0.UserLookup();
    var result = userLookup.getUserDetails(newValue);

    if (result.success) {
        // Populate the fields with user details
        g_form.setValue('first_name', result.firstName);
        g_form.setValue('last_name', result.lastName);
        g_form.setValue('manager', result.manager);

        // Show success message briefly
        g_form.addInfoMessage('User details populated: ' + result.firstName + ' ' + result.lastName);
    } else {
        // Show error message
        g_form.addErrorMessage(result.message);
        g_form.clearValue('caller'); // Clear the invalid selection
    }
}
